  timeout: 6000
}).then($lines => {
  const total = $lines.length;
  cy.log(`📋 Nombre total de lignes dans le panier : ${total}`);
  if (total < 2) {
    cy.log(`⚠️ ANO-UI-02 — Panier incomplet : ${total} ligne(s) trouvée(s), attendu ≥2`);
  } else {
    cy.log(`✅ ÉTAPE 4 — ${total} ligne(s) confirmée(s) dans le panier`);
  }
});
// ── ÉTAPES 5-N : Supprimer toutes les lignes une par une ──
const supprimerToutesLesLignes = () => {
  cy.get("body").then($body => {
    if ($body.find("[data-cy='cart-line-delete']").length > 0) {
      cy.intercept("DELETE", "**/orders/**/delete").as("deleteOneLine");
      // ✅ forcer le re-query après re-render Angular
      cy.get("[data-cy='cart-line-delete']", {
        timeout: 6000
      }).should("exist").first().click({
        force: true
      });
      cy.wait("@deleteOneLine", {
        timeout: 6000
      }).then(interception => {
        cy.log(`📡 Status suppression ligne : ${interception.response.statusCode}`);
        expect(interception.response.statusCode).to.be.oneOf([200, 204]);
      });
      // ✅ attendre que Angular re-rende le DOM avant récursion
      cy.wait(500);
      supprimerToutesLesLignes();
    }
  });
};
supprimerToutesLesLignes();
